public async Task<ProductDto> GetAsync(int id, CancellationToken ct)
{
    var key = $"product:{id}";
    var cached = await _db.Cache.GetAsync<ProductDto>(key, ct);
    if (cached is not null) return cached;

    // Only one caller repopulates; the rest await the same entry (stampede guard).
    var entry = await _singleFlight.OnceAsync(key, async () =>
    {
        var dto = await _db.Products.AsNoTracking()
            .Where(p => p.Id == id)
            .Select(p => new ProductDto(p.Id, p.Name, p.Price))
            .FirstOrDefaultAsync(ct);

        if (dto is not null)
        {
            // Short TTL + jitter so hot keys don't all expire at the same instant.
            var ttl = TimeSpan.FromSeconds(30 + _random.Next(0, 10));
            await _db.Cache.SetAsync(key, dto, ttl, ct);
            await _db.Cache.TagAsync(key, $"product:{id}");   // for eviction below
        }
        return dto;
    }, ct);

    return entry;
}

// Write path — DB first, then evict (never update-in-place)
public async Task UpdatePriceAsync(int id, decimal price, CancellationToken ct)
{
    await using var tx = await _db.Database.BeginTransactionAsync(ct);
    var product = await _db.Products.FirstAsync(p => p.Id == id, ct);
    product.Price = price;
    await _db.SaveChangesAsync(ct);          // 1) source of truth committed
    await tx.CommitAsync(ct);

    await _db.Cache.EvictAsync($"product:{id}", ct);   // 2) then evict
    await _cacheBus.PublishAsync($"product:{id}.changed"); // other pods/instances
}

// What NOT to do:
// - cache.Set(...) with a stale value on write: a concurrent reader can
//   overwrite your new value with the old one it loaded moments earlier.
// - TTL of 10 minutes on price data with no invalidation: your staleness
//   budget is now 'up to 10 minutes of wrong money'.
